CREATE TABLE IF NOT EXISTS roles(id INT PRIMARY KEY, name VARCHAR(30) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS permissions(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS role_permissions(role_id INT NOT NULL, permission_id INT NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(permission_id) REFERENCES permissions(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS users(id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role_id INT NOT NULL, active BOOLEAN NOT NULL DEFAULT 1, session_version INT NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(role_id) REFERENCES roles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS zones(id INT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS provinces(id INT PRIMARY KEY, zone_id INT NOT NULL, name VARCHAR(80) NOT NULL UNIQUE, UNIQUE(id,zone_id), FOREIGN KEY(zone_id) REFERENCES zones(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS product_types(id INT PRIMARY KEY, name VARCHAR(60) NOT NULL, active BOOLEAN NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS product_variants(id INT AUTO_INCREMENT PRIMARY KEY, product_type_id INT NOT NULL, size VARCHAR(30) NOT NULL, price_satang BIGINT NULL, active BOOLEAN NOT NULL DEFAULT 0, UNIQUE(product_type_id,size), CHECK(price_satang IS NULL OR price_satang BETWEEN 1 AND 9999999999), FOREIGN KEY(product_type_id) REFERENCES product_types(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS zone_product_images(zone_id INT NOT NULL, product_type_id INT NOT NULL, filename VARCHAR(80) NULL, PRIMARY KEY(zone_id,product_type_id), FOREIGN KEY(zone_id) REFERENCES zones(id), FOREIGN KEY(product_type_id) REFERENCES product_types(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS bank_settings(id INT PRIMARY KEY, bank_name VARCHAR(100) NOT NULL DEFAULT '', bank_code VARCHAR(10) NOT NULL DEFAULT '', bank_number VARCHAR(40) NOT NULL DEFAULT '', name_th VARCHAR(150) NOT NULL DEFAULT '', name_en VARCHAR(150) NOT NULL DEFAULT '', account_type VARCHAR(20) NOT NULL DEFAULT 'NATURAL', extra_verify VARCHAR(255) NOT NULL DEFAULT '', easyslip_account_id VARCHAR(100) NULL, CHECK(id=1)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS app_settings(name VARCHAR(80) PRIMARY KEY, value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS orders(id BIGINT AUTO_INCREMENT PRIMARY KEY, reference VARCHAR(40) COLLATE utf8mb4_bin NOT NULL UNIQUE, token_hash CHAR(64) COLLATE utf8mb4_bin NOT NULL, idempotency_key CHAR(64) COLLATE utf8mb4_bin NOT NULL UNIQUE, request_hash CHAR(64) NOT NULL, zone_id INT NOT NULL, province_id INT NOT NULL, customer_name VARCHAR(150) NOT NULL, phone VARCHAR(30) NOT NULL, address TEXT NOT NULL, total_satang BIGINT NOT NULL, quantity INT NOT NULL, status ENUM('pending_payment','paid','underpaid','overpaid','review','cancelled','fulfilled') NOT NULL DEFAULT 'pending_payment', bank_snapshot JSON NOT NULL, paid_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(total_satang>0), CHECK(quantity>0), FOREIGN KEY(zone_id) REFERENCES zones(id), FOREIGN KEY(province_id,zone_id) REFERENCES provinces(id,zone_id), INDEX(status,created_at), INDEX(zone_id,province_id,created_at), INDEX(customer_name), INDEX(phone)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS order_items(id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL, variant_id INT NOT NULL, product_name VARCHAR(60) NOT NULL, size VARCHAR(30) NOT NULL, quantity INT NOT NULL, unit_satang BIGINT NOT NULL, CHECK(quantity BETWEEN 1 AND 999), CHECK(unit_satang>0), FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(variant_id) REFERENCES product_variants(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS privacy_acknowledgements(order_id BIGINT PRIMARY KEY, version VARCHAR(50) NOT NULL, acknowledged_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS payment_attempts(id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL, idempotency_key VARCHAR(64) COLLATE utf8mb4_bin NOT NULL, filename VARCHAR(80) NOT NULL, file_hash CHAR(64) NOT NULL, status ENUM('processing','verified','underpaid','overpaid','rejected','duplicate','review') NOT NULL DEFAULT 'processing', reason VARCHAR(255) NOT NULL DEFAULT '', amount_satang BIGINT NULL, transaction_reference VARCHAR(128) COLLATE utf8mb4_bin NULL, result JSON NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at DATETIME NULL, UNIQUE(order_id,idempotency_key), UNIQUE(order_id,file_hash), FOREIGN KEY(order_id) REFERENCES orders(id), INDEX(status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS payment_reference_claims(transaction_reference VARCHAR(128) COLLATE utf8mb4_bin PRIMARY KEY, order_id BIGINT NOT NULL, attempt_id BIGINT NOT NULL UNIQUE, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(attempt_id) REFERENCES payment_attempts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS payment_approvals(id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL UNIQUE, attempt_id BIGINT NOT NULL, actor_id BIGINT NOT NULL, reason TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(attempt_id) REFERENCES payment_attempts(id), FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS order_notes(id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL, actor_id BIGINT NOT NULL, note TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT NULL, action VARCHAR(80) NOT NULL, target VARCHAR(100) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_id) REFERENCES users(id), INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS rate_limits(bucket CHAR(64) PRIMARY KEY, hits INT NOT NULL, expires_at BIGINT NOT NULL, INDEX(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
